 {id:"httpl",zone:"zHttp",cls:"core",x:227,y:56,w:173,h:42,l:["Agent door"],sub:["127.0.0.1:4747 · local pipe"],
  role:"mcp-http-handler's host half, the agents' only door into hetu. It is a core plugin in a utilityProcess with its own port to the router. Electron can't sandbox a utilityProcess, so it keeps its crashes and memory apart from main but not its privilege. So it stays minimal: Node's HTTP server on loopback, the Host and Origin checks, rate and size limits and a token seam. Beside it is a local pipe for programs on your computer, which the stdio shim reaches: a named pipe of your own user on Windows, a socket in a folder only you may open elsewhere. Both are open only while an mcp plugin is there, so with none built they stay closed. Windows use IPC and plugins use ports, so neither needs a token.",
  where:"mcp-http-handler, utilityProcess",trust:"Trusted base, install only, not sandboxed",does:["Plain HTTP bound to 127.0.0.1:4747, another Host or any Origin answers 403","50 requests a second, 8 KiB of headers and 512 KiB of body","No token: 401 with a bare WWW-Authenticate: Bearer while no token is issued yet","A token's label must read client id, # and a number, else 401","Each request or pipe line becomes one mcp.handle call with the client's label as onBehalf","8 calls in flight per client and 32 in all, answers up to 4 MiB","The pipe takes one JSON-RPC message a line and no token, its first line names the client","A new client on the pipe waits for your Confirm of its connect, one you revoke has its connections closed at the next poll, every 3 s","A port or pipe already taken fails the bind, no other is tried","Refusals counted by reason for the core, never a Host, a token or a body"],dec:["HTTP for agents only, IPC for windows"],th:[14,15,50]},
 {id:"oauth",zone:"zHttp",cls:"core",x:410,y:56,w:173,h:42,l:["OAuth server"],sub:["planned · not built"],
  role:"Planned, not built. hetu's own local authorization server inside mcp-http-handler, from a certified library. hetu writes the policy: consent, scopes, client rules and token lifetimes. The library reflects any Host, so the listener's checks sit in front of it. The core's connect, core.consentAsk, is built and the local pipe already raises it for each new client, so OAuth is to use the same Confirm.",
  where:"mcp-http-handler, utilityProcess",trust:"Trusted base, install only",does:["OAuth 2.1 with PKCE, resource-bound tokens","Short-lived access tokens, refresh rotation with reuse detection","Fetches client metadata over HTTPS only, never private addresses","Asks the human to connect each client in the trusted window"],dec:["MCP OAuth spec"],th:[9,50,51]},

 {id:"boot",zone:"zCore",cls:"core",x:227,y:148,w:173,h:46,l:["Boot"],sub:["trust for one run"],
  role:"Sets up trust for one run, before any module or plugin runs. It takes the folder lock, opens the one event log and loads the security state, checking each file against its hash line. Then it hands the state to the plugins manager and the log to recording and owns nothing. It can't be switched off: something must check the state before anything else runs.",
  where:"Core, Electron main process",trust:"Trusted core, can't be switched off",does:["Folder lock, then one EventLog and one StateStore for the run","Hash line checked before the strict parser reads a file","Reads a format 2 file and writes it back once in format 3, the old agent fields dropped","Reads a newer format without writing over it, tells a wipe from a first run","Writes defaults and its own records"],dec:["Secure Boot model","Hash checked on load"],th:[24,25,54,55]},
 {id:"plugins-manager",zone:"zCore",cls:"core",x:410,y:148,w:173,h:46,l:["Plugins manager"],sub:["check · place · identity"],
  role:"Decides what may run, where, when and as whom. It reads the install list and every manifest with the strict parser. It reads each plugin's files once, hashes the bytes and keeps exactly those to run. It places each half by where its code came from, never by what it declares. It mints every port and registers each with the router in the same step. It owns every plugin's lifecycle, starts the core modules and applies confirmed changes to the security state. It calls the router and the router reaches it only through the actions it handed in.",
  where:"Core, Electron main process",trust:"Trusted core, can't be switched off",does:["Hashes once and runs exactly the hashed bytes","Signer pairing, reserved ids, the requires graph and start order, each core module a node of it","Mints every port, owns lifecycle, the restart marker and the start markers","Keeps first-party copies in step with the install, stages updates","Applies confirmed changes, pushes a numbered grants snapshot to the gate","Hands the grant risk classifier the whole table at every class change and orders the writes by the classes it stores","Holds each pair's items in memory for one run, with the pairs the human revoked","Raises a client's connect for the handler and tells it which clients you revoked","Does the ping, the mark and the kill the heartbeat asks for","Never runs plugin code, decides a grant or restarts a plugin on its own"],dec:["Check before load","Identity from the way in, never the message"],th:[24,26,32,34,35,47]},
 {id:"router",zone:"zCore",cls:"core",key:true,x:227,y:206,w:356,h:52,l:["Router"],sub:["ways in · eleven steps · the floor"],
  role:"The one path every call and event takes and the point where the rules are enforced. It binds the caller from the way in, never from the message, then runs each kind of call through one fixed sequence: shape, floor, ceiling, precheck, route, prepare, decide, guard, perform and record. It asks flood control, the gate and the guards, routes to the server of each namespace and hands each call's record to recording. It never decides a grant and never holds a call open waiting for you. The gate decides, the router routes.",
  where:"Core, Electron main process",trust:"Trusted core, can't be switched off",does:["Ways in: a port per plugin half, a utility half's included, window IPC with the sender check first","Eleven steps: bind, shape, floor, ceiling, precheck, route, prepare, decide, guard, perform, record","The floor: rules that hold with every module and plugin off","A chain under a plugin root carries a pair: the root plugin's id and the onBehalf it set","A window's onBehalf is attribution only, never judged","On a new grants snapshot every open call with power is judged again, one no longer allowed ends stale","Core and security actions go to the part handed in for them, never asked of the gate"],dec:["Mechanism in the core, policy in modules","Zero trust enforcement point","No plugin has power of its own"],th:[22,31,32,37,39]},
 {id:"bus",zone:"zCore",cls:"core",x:227,y:270,w:173,h:44,l:["Event bus"],sub:["in the router · canList"],
  role:"Delivers events: a signal plus a path, only for notes the subscriber may list and never content. Topics are owned, so a plugin publishes only the topics it declared and the luoshu publishes its two from inside the core. It asks the gate's canList on every delivery and caps unacknowledged events per subscriber.",
  where:"Core, inside the router",trust:"Trusted core",does:["luoshu.changed for hetu's own writes, luoshu.outside for writes from outside","canList: the gate's answer when on, true when you switched it off, false while it is down","256 unacknowledged events per subscriber, then one events.dropped","Subscriptions asked again on every gate change and every new grants snapshot"],dec:["Events carry a signal and a path, never content"],th:[37]},
 {id:"modules",zone:"zCore",cls:"core",x:410,y:270,w:173,h:44,l:["Modules holder"],sub:["start · switch · fail-safe"],
  role:"Holds the eleven core modules, made once when the core is joined. It starts them as the plugins manager starts, the fail-safe controls first and alone: the gate, flood control and the lock. Then it hands each what it needs on every change: the gate its grants snapshot, exec its view of the grants, the luoshu, history and the lock the notes folder. It answers the router and the plugins manager with a module only while that module is on, except flood control and the security view, which answer from the first call unless you switched them off. A start or a push that throws marks the module failed until one goes through.",
  where:"Core, Electron main process",trust:"Trusted core, can't be switched off",does:["The three fail-safe controls, the gate, flood control and the lock, start first and alone","A start marker for each from before its start to its first push, so a start that hung main stops the next launch in the fail-safe","One of them failed at start: no other module begins and hetu stops in the fail-safe","A module switched off is closed and its step acts as if it didn't exist","Each start within a time limit, one past it marked failed","Flood control, recording, the security view and the lock run on through shutdown and the stopped mode"],dec:["One rule for every yes or no control"],th:[35,39]},
 {id:"runtime",zone:"zCore",cls:"core",x:227,y:326,w:173,h:46,l:["Runtime"],sub:["the only Electron code"],
  role:"Builds and keeps the isolated places plugins run: sessions per role, protocol handlers, CSP headers and request filters, the hidden renderers with a worker host page each, data: workers, windows and frames and the utilityProcess of a utility half. It runs terminate() and reports what the renderer knows, a renderer that died with the plugins it held and a worker's error and drop counts, but never decides when to stop or restart a plugin.",
  where:"Core, Electron main process",trust:"Trusted core, can't be switched off",does:["The shipped build exits on any argument but --mcp-stdio and on a debugging switch","Every session in memory and offline, permission handlers deny all","Starts workers from the verified bytes, views from single-use URLs","Forks a utility half from its verified bytes with an environment built from empty","terminate() on a stop or a crash","Quits when the last window a human sees closes","hetu --mcp-stdio runs only the stdio shim: no boot, no event log, no window, stdin and stdout relayed to the local pipe, hetu started first when none answers"],dec:["The core measures and stops, the human decides"],th:[21,29,36,42,44]},
 {id:"api",zone:"zCore",cls:"core",x:410,y:326,w:173,h:46,l:["core/api · lib · SDK"],sub:["shared code, no policy"],
  role:"Shared code with no policy. core/api holds the request shapes, refusal codes, change kinds, the fixed capability list with the types a pair may hold, the scope grammar and matcher, the manifest schema, reserved ids, the core module lists, the expected guards, the namespace table, the local pipe's name, the window grant table, the limits, the grant risk classifier's interface, the editor bridge and ui shapes, the storage quotas and the history and exec caps, with no I/O, Node or DOM. core/lib holds the event log, the strict parser with the hash line, file hashing, the path canonicaliser and the clean environment. The SDK gives plugins one call per action and a typed refusal.",
  where:"Core code, with the SDK inside each plugin",trust:"Trusted core",does:["One grammar for display, storage and matching","The canonicaliser refuses .git, dot names, stream names and short-name tricks","The SDK holds no security: raw messages get the same checks","Plugin code makes the same calls in every gate state"],dec:["A fixed list of capability types","An SDK library, not a plugin"],th:[3,30,54]},

 {id:"gate",zone:"zMods",cls:"core",key:true,x:227,y:424,w:173,h:42,l:["Gate"],sub:["precheck · decide · canRead"],
  role:"The policy engine the router asks about every call with power. It answers a precheck on the raw request, decides on the canonical object the provider prepared and answers canRead for events. A call made under a pair needs the caller's items and the pair's both. It never routes a call and touches no disk. Switched off by you, its step doesn't exist and every call passes, whatever the log's state. If it can't take a grants snapshot while hetu runs, calls with power fail closed. If it fails at start, hetu stops in the fail-safe.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["Precheck: does the caller hold this type and a matching scope, before anything touches the disk","Decide: allow, refuse or ask on the canonical object","A pair's items count only for luoshu.read, luoshu.list, luoshu.write, history and lock.set, a revoked pair holds none","canRead and canList for events and listings, for the pair too","Answers on a numbered grants snapshot, an older answer is refused","Serves gate.reach and gate.filterReadable"],dec:["No plugin has power of its own","The gate is a core module","Allow all, the log decides nothing"],th:[1,3,9,27,30,31,39,40]},
 {id:"classifier",zone:"zMods",cls:"core",x:410,y:424,w:173,h:42,l:["Grant risk classifier"],sub:["classes · screens · notices"],
  role:"Classes what every plugin can reach and writes the plain-text lines for the approval screens. The plugins manager hands it the whole table of plugins and grants at every class change. It answers for every plugin the change moves, with the items that ask at their first use and whether an update loads without a Confirm. The core checks each answer's shape and orders the writes. Switched off, classes stay as last stored, every item not confirmed asks at its first use and nothing updates on its own. Down, every class counts as the highest.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["Class from the reachable set, never declared","Read plus network ranks class 4, followed through plugin.call and events","Only class 0 updates without a Confirm","Names the items that ask at first use","A move up with no Confirm on screen raises a notice when it leaves 0 or enters 4"],dec:["Plugin classes"],th:[27,28,48]},
 {id:"flood",zone:"zMods",cls:"core",x:227,y:474,w:173,h:42,l:["Flood control"],sub:["rates · flood cap · in flight"],
  role:"Bounds what plugins and windows may cost main. It counts each way's messages against its rate and its flood cap, then each caller's calls and bytes in flight. It says yes or no while the router acts on the answer. Switched off by the human, nothing is counted, dropped or closed. A throw in it drops that one message or fails that one call.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["Over 1,000 messages a second on one way in: dropped with no reply","Past the flood cap, ten times the rate across 5 s, a plugin's port is closed and it reads crashed, a window's never","64 calls and 32 MiB in flight per caller and per chain root, then throttled","Paces each plugin's messages at the worker host page and at a utility half's port"],dec:["One rule for every yes or no control"],th:[7,36]},
 {id:"heartbeat",zone:"zMods",cls:"core",x:410,y:474,w:173,h:42,l:["Heartbeat"],sub:["pings · three misses"],
  role:"Watches each running plugin for a hang. Every 5 s it has the plugins manager ping each plugin and three misses in a row ask the core to mark a worker unresponsive or kill a utility half. The ping, the mark and the kill stay the core's. It is no security control, but switching it off waits for one Confirm. Switched off, nothing is pinged, marked or killed and a call to a hung plugin fails on its own deadline.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["A ping every 5 s, three misses read unresponsive","A worker marked unresponsive answers timeout at once, nothing closed","A utility half that stops answering is killed and reads crashed","You can still stop a plugin from the plugin list"],dec:["The core measures and stops, the human decides"],th:[36]},
 {id:"recording",zone:"zMods",cls:"core",x:227,y:524,w:173,h:42,l:["Recording"],sub:["core records · audit queue"],
  role:"Writes what happens to the one event log boot opened, in two lanes. Core records go first: boot and plugin checks, crashes, security requests, Confirms and what was applied. Audit records wait in a queue of up to 10,000, written every 100 ms, up to 256 records with one fsync. It enforces nothing: the step that asked decides whether to wait for a record. Windows read the log through log.segments and log.verify. Switched off, nothing lands and the switch's own record is the last one.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["Core records: checks, crashes, requests, Confirms, applied changes","Audit records: caller, onBehalf, action, scope, outcome, never note text","A failed batch goes again alone under the same id, so it lands once","A bounded backlog while the log can't write, counted if it overflows","A widening change waits for its record, unless recording is off","A record left unwritten for 30 s restarts hetu once, then stops it in the stopped mode"],dec:["The core writes its own records","Detection"],th:[11]},
 {id:"secview",zone:"zMods",cls:"core",x:410,y:524,w:173,h:42,l:["Security view"],sub:["which change waits"],
  role:"In the path of every security change a window asks for, as the gate is in the path of every call. It holds the rules the trusted window applies: whether a change applies at once, lands its record first or waits for a Confirm, whether a click counts and which id must be typed first. The trusted window, its session and its sender check stay the core's and can't be switched off. Switched off, no security control can be switched off, every other change applies with its record first and the editor window may only switch the view on again.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["A narrowing applies at once, its record after","A widening waits for a Confirm in the trusted window","A Confirm counts only for the request first in line, after the input delay","Switching a security control off asks for its id typed first","While it is off, every security control is drawn locked"],dec:["Security confirmation in a separate page"],th:[22,33]},
 {id:"luoshu",zone:"zMods",cls:"core",x:227,y:574,w:173,h:42,l:["Luoshu"],sub:["the only writer of notes"],
  role:"Serves luoshu reads, writes, removes, moves and listings and is the only code that writes notes. It turns each request path into a canonical one, holds a latch on the path from prepare to perform and checks the version before every write, with the lock module's guard asked in between. Its watcher flags writes made around hetu. Its folder comes from state/luoshu.json.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["Canonical paths: refuses .git, dot names, stream names and hetu's own folders","A latch on the path from prepare to perform","Version check, a stale edit is refused","The note's folder looked at again right before each act","Publishes luoshu.changed and luoshu.outside through the router","Off or failed, or with no folder picked: every call answers unavailable"],dec:["One path to disk for notes"],th:[1,2,3,10,26,30]},
 {id:"storage",zone:"zMods",cls:"core",x:410,y:574,w:173,h:42,l:["Storage"],sub:["own space per caller"],
  role:"Serves storage and cache for every plugin and for the editor window. Each caller gets its own space, always granted, with a quota and unreadable by others. Every call is keyed by the caller the router names, so a plugin has no way to name another one. Each key ends in its own hash line.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["A key that fails its hash answers tampered and the plugin decides","The cache is rebuildable and cleared on a new version","Off or failed: calls answer unavailable, plugins run without persistence"],dec:["Registry and plugin storage"],th:[32]},
 {id:"history",zone:"zMods",cls:"core",x:227,y:624,w:173,h:42,l:["History"],sub:["shadow repo · plumbing"],
  role:"Keeps hetu's own git history in a repo outside the luoshu, one per notes folder under the data folder. A plugin holding history commit asks for history.commit, one holding history read for history.log and history.read, each judged on its paths. It reads each note's bytes itself and runs git plumbing only, with --git-dir alone from an empty folder of its own, so nothing planted in the luoshu's git config, hooks, filters or nested repos ever runs.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["history.commit, history.log and history.read, each judged on its access and paths","hash-object --no-filters --stdin, update-index --index-info, write-tree, commit-tree --no-gpg-sign","Also read-tree, update-ref, rev-parse, rev-list, diff-tree and cat-file, with init --bare --template= once for the repo","Reads at most 16 MiB a note and 64 MiB a commit","Environment built from empty, git found by its real path outside the notes and data folders","Under a pair the root plugin commits and the pair's field is the author, otherwise the caller commits","A restore reads the old text and writes it through the luoshu","With no git, off or with the luoshu off: its calls answer unavailable"],dec:["Shadow repo"],th:[13,45]},
 {id:"exec",zone:"zMods",cls:"core",x:410,y:624,w:173,h:42,l:["exec"],sub:["exact commands"],
  role:"Runs the exact argument arrays a plugin declared, with an environment the core builds from scratch. It checks the caller's command against its read-only view of the grants even with the gate off, unless you switched on any command for that plugin. An exec item you switched off counts for nothing, with the gate off too. Neither the program nor any argument may name a file in the notes folder or the data folder, by real path.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["Exact argument arrays, checked with the gate off too","A program by its real absolute path, a new empty working folder each run","Variables by name only, never one that loads code (NODE_OPTIONS, PYTHONPATH, LD_PRELOAD…)","Refuses a program or an argument naming a file in the luoshu or the data folder","1 MiB each of stdout and stderr, four commands at once a caller","Off: what runs is ended and calls answer unavailable"],dec:["What exec really grants","Clean environment"],th:[45,46]},
 {id:"lock",zone:"zMods",cls:"core",x:227,y:674,w:173,h:42,l:["Lock"],sub:["note locks · the guard"],
  role:"Holds note locks and is the one guard the router asks on every luoshu write, remove and move. While a holder's lock is on a note, no other holder's write, remove or move reaches it, yours included until you take the note over. The holder is the chain's own: the root plugin with the whole onBehalf field, or the window, never a name in the arguments. Locks live in memory for the run. The leases plugin is to decide who gets one. Switched off by you, its step doesn't exist and every write passes. Failed while hetu runs, every note write answers guard-down. If it fails at start, hetu stops in the fail-safe.",
  where:"Core module, Electron main process",trust:"Trusted base, bundled into main, can be switched off",does:["lock.set locks every path or none for up to 30 minutes and renews the caller's own","At most 1,024 live locks per root plugin, 256 per client (the field up to its first #, so one client's sessions count together) and 64 paths a call","lock.clear clears only the caller's own chain's locks, a window clears any","lock.held says which paths are locked, never by whom","The guard answers from its own table with no await, a move's both ends","Case, Unicode form and short names of one note meet on one key","Another notes folder frees every lock","A write already past the guard when a lock is set can still land"],dec:["A guard fails closed unless you switched it off","One writer per note"],th:[1,2,4,6,7,39]},

 {id:"net",zone:"zPlanned",cls:"core",x:227,y:762,w:173,h:30,l:["net"],sub:["net.fetch · planned"],
  role:"Planned, not built. It is to serve net.fetch to the hosts a plugin was granted. Every session stays offline, so a plugin's own code reaches no network. A plugin that can read notes and reach the network ranks in the highest class.",
  where:"Core plugin in a utility process of its own, once built",trust:"Trusted base, install only, can be switched off",does:["Host list from the grant","Read plus network ranks class 4"],dec:["Plugin classes"],th:[44]},

 {id:"osproc",zone:"zProc",cls:"proc",x:227,y:830,w:356,h:34,l:["OS process"],sub:["git plumbing · exact exec commands"],
  role:"Where exec and history land: a real process running as you, outside Chromium and outside the router. That's why exec is class 4 and no program or argument may name a file in the luoshu or the data folder, where a plugin could have written it.",
  where:"Your OS user",trust:"Leaves the sandbox",does:["git with --git-dir pointing at the shadow repo","Exact commands a plugin declared, or any command once you switched that on for it"],dec:["What exec really grants"],th:[13,45,46]},

 {id:"whost",zone:"zHidden",cls:"core",x:622,y:56,w:140,h:44,l:["Worker host page"],sub:["fixed core page"],
  role:"One of the three fixed core pages. It receives verified bytes from the plugins manager, starts each plugin as a data: worker, checks and paces each worker's messages before main has to read them, holds each worker's port to the drawer under the same checks and terminates workers. Nothing else. A short core prelude runs first in each worker and removes Worker and SharedWorker, so a plugin can't start another global.",
  where:"Hidden renderer, fixed core page",trust:"Trusted core page",does:["Starts a worker from a data: URL holding the hashed bytes","Each data: worker gets an opaque origin and a copy of the page's CSP","No eval and no network, WebAssembly works","Anything but plain JSON text within the cap, or a flood, cuts the worker off, a message over the rate or byte budget is dropped","terminate() on a stop, a crash or a cutoff"],dec:["Isolation mechanism"],th:[26,29,44]},
 {id:"layout",zone:"zHidden",cls:"sandbox",x:773,y:56,w:140,h:44,l:["Layout"],sub:["data: worker"],
  role:"hetu's own layout, a first-party plugin the install carries and copies into the plugin folder. It holds ui.layout and storage and nothing else, so it reads no note and learns no note's path. It draws the skeleton the drawer lays views, editors and titles over. You can pick another layout in the views menu, a normal setting with no Confirm.",
  where:"First-party hidden renderer, data: worker",trust:"First-party, sandboxed",does:["Three columns over a status row, a side folding to a rail when the window is too narrow","Keeps the arrangement in its own storage by view","The drawer runs drags and resizes and sends it only the result"],dec:["The core draws, plugins decide"],th:[64]},
 {id:"hmarks",zone:"zHidden",cls:"sandbox",x:622,y:112,w:140,h:44,l:["Hidden marks"],sub:["data: worker"],
  role:"First-party plugin that hides markdown's markers and styles the text while you type. Its worker keeps a copy of each note you opened, read with editor.read and kept in step with each change, parses it and sends the marks for the range the editor draws over the editor bridge, at most 5,000 a note. The text itself never changes and Ctrl+/ always shows the real text. The drawer's own rules decide how the caret, deletes and selections treat hidden text.",
  where:"First-party hidden renderer, data: worker",trust:"First-party, sandboxed",does:["Holds ui.read and ui.edit on every note, ui.decoration, ui.command, ui.view and storage, never luoshu.read or luoshu.write","Format keys such as Mod-b, each an edit for the version the key came at","Its settings are a status row item, kept in its storage","A median of 1.2 ms from a key typed to its mark on a 2,000-line note"],dec:["Editor API"],th:[19,41]},
 {id:"gitp",zone:"zHidden",cls:"sandbox",x:773,y:112,w:140,h:44,l:["Git"],sub:["planned · not built"],
  role:"Planned, not built. First-party plugin from the plugin folder. It is to ask history for commits and history reads. History runs git against the shadow repo, so a commit never reads the luoshu's git config.",
  where:"First-party hidden renderer, data: worker",trust:"First-party, sandboxed",does:["Asks history.commit for new writes","History and revert views"],dec:["Shadow repo"],th:[13]},
 {id:"mcp",zone:"zHidden",cls:"sandbox",x:622,y:168,w:291,h:44,l:["MCP plugin"],sub:["data: worker · planned · not built"],
  role:"Planned, not built. It is to turn MCP requests into calls on the router. mcp-http-handler reaches it from its HTTP door and its local pipe through its own plugin.call item, with the client's label as onBehalf. Every call it makes under that root call is judged on its own items and the pair's both, so a client never gets more than the MCP plugin holds. It asks the human for the pair's items through core.identityAsk. As a first-party plugin it would share the first-party hidden renderer.",
  where:"First-party hidden renderer, data: worker",trust:"First-party, sandboxed",does:["Tools to read, list, write and edit notes, read a note's history and ask for access","A pair's items: luoshu.read, luoshu.list, luoshu.write, history and lock.set only","Asks for a pair's items, which the human grants for one run","Calls luoshu, history and lock under the client's onBehalf"],dec:["Agents behind MCP"],th:[6,9,40]},
 {id:"community",zone:"zComm",cls:"sandbox",x:622,y:264,w:140,h:42,l:["Community plugin"],sub:["one renderer each"],
  role:"Any plugin you installed. The same wall as first-party plugins: a data: worker in a hidden renderer of its own, holding one port to the core and, when it holds a ui item, one to the drawer for its ui verbs. Its class is computed from what it requests and what it reaches.",
  where:"Its own hidden renderer, data: worker",trust:"Untrusted, sandboxed",does:["Signing is designed, not built: an unsigned build runs only in dev mode or when its hash is on the allowed list, which no button sets yet","Only class 0 updates without a prompt","Calls through the SDK, raw messages get the same checks"],dec:["Plugin classes","Signing and updates"],th:[27,28,29,44,46,47]},
 {id:"leases",zone:"zComm",cls:"sandbox",x:773,y:264,w:140,h:42,l:["Leases"],sub:["community · planned"],
  role:"Planned, not built. A community plugin holding the lease logic for agents: which notes an agent's tool may lock, for how long and when to renew. It sets and clears locks through the lock module, which is built and does the refusing.",
  where:"Its own hidden renderer, data: worker",trust:"Untrusted, sandboxed",does:["Decides who gets a lock, on which notes and for how long","Sets, renews and clears locks through lock.set and lock.clear","Holds no power of its own beyond its lock.set grant"],dec:["One writer per note"],th:[7]},

 {id:"views",zone:"zEditor",cls:"sandbox",x:622,y:392,w:291,h:44,l:["Views and layouts"],sub:["plugin trees · frames · the layout"],
  role:"What plugins draw in the editor window. A plugin declares views in its manifest and draws each as a tree of the drawer's building blocks, or as a sandboxed frame for a canvas or a framework of its own. The layout you picked, hetu's own unless you pick another, draws the skeleton and places views, notes and titles in it, but never sees another plugin's nodes, input or a note's path. Redrawing gives no reach: a plugin still reads and writes only what its grants allow.",
  where:"Editor window: trees drawn by the drawer, frames in their own process",trust:"Sandboxed",does:["Trees as data: no markup, no stylesheets, styles checked one value at a time","Frames load once from a single-use URL with their plugin's CSP, allow-scripts only, a port on the first load only","What you click or type in a view goes to its owner and no one else","Themes are token values, the editor's text keeps its contrast"],dec:["The core draws, plugins decide","Start narrow, widen on demand"],th:[17,20,21,41,44,64]},
 {id:"eshell",zone:"zEditor",cls:"core",x:622,y:458,w:291,h:44,l:["Drawer"],sub:["window page · layers · bridge · core keys"],
  role:"The editor window's page, core code. It holds the editor, the raw view, the quick-open palette, the views menu and the banner, takes the core keys before anything else, draws what plugins send in layers below its own and serves the editor bridge and the ui verbs at its end of each plugin's port. The editors, titles and frames sit above the layout's own nodes, so no layout covers them. Main makes that port for each plugin worker holding a ui item and each page load and names its owner. Every verb reaches a note only with what the gate gives that plugin there. The banner works with every plugin off.",
  where:"Editor window, fixed core page",trust:"Trusted core page",does:["Window IPC to the router, the sender checked first","A port per plugin worker, relayed as text within the plugin's cap and rate","Bridge: read, decorate, edit, key bindings and the key stream, each with the plugin's read and ui reach for that note, never its luoshu.write","Late marks mapped through what you typed, stale edits rebased and refused only when they touch text changed since","Core keys first: the raw view, quick open, save and Quit","Drags and resizes run in the page, only the result goes to the layout","Banner: core modules off, the log unable to write, crashed plugins, kinds of state file that failed their check, pending requests"],dec:["Editor API","Trusted surfaces are core pages"],th:[22,33,41,42,44]},
 {id:"ecore",zone:"zEditor",cls:"core",x:622,y:524,w:291,h:48,l:["Editor"],sub:["CodeMirror · raw view · drawn marks"],
  role:"CodeMirror in the drawer, one view per open note, with the raw view. CodeMirror decides nothing, so it is core mechanism and no plugin. The page parses markdown and draws the marks plugins send with its own classes. What hides is the hidden marks plugin's, a first-party worker behind the editor bridge, so no plugin's code runs in the page. The editor owns the text, cursor and undo and saves as your window. It holds no Node power but reads every open note and keystroke, so it stays minimal and trusted. The raw view ignores every plugin decoration.",
  where:"Editor window page",trust:"First-party, in-page, trusted base",does:["Hidden text follows the drawer's own rules: the caret, arrows, deletes and selections treat it alike for every plugin","Ctrl+/ shows the real text over the whole window, no plugin reaches it","Saves as your window, naming the plugins whose edits the text carries","Drafts kept in the window's storage until a save lands"],dec:["Editor API, locked in","Two places run outside the isolation"],th:[8,19,41,42]},
 {id:"content",zone:"zEditor",cls:"sandbox",x:622,y:592,w:291,h:40,l:["Content frames"],sub:["artifacts · note content · not built yet"],
  role:"Designed, not built. Frames that render note content such as artifacts, under the core's strict CSP. Each frame's port ends at the router, which relays capped messages to the plugin that asked. On the floor, content gets no identity and no network. The artifacts plugin brings an identity per frame that may read its own note or fetch declared hosts, never both and never more than its plugin holds.",
  where:"Editor window, opaque-origin frames",trust:"Sandboxed, no identity on the floor",does:["Loaded once from a single-use content URL","Port relayed by the router, messages capped","Read its own note or fetch declared hosts, never both"],dec:["Artifacts"],th:[5,17,18,20,44]},

 {id:"trusted",zone:"zTrusted",cls:"core",key:true,x:622,y:684,w:291,h:72,l:["Trusted window"],sub:["one request at a time","plugins · switches · identities · limits"],
  role:"A fixed core page at hetu://trusted, in its own session with no plugins and no note content. It shows one pending request at a time, drawn from the core's own text, then the plugin list, the switches, dev mode, the notes folder, the identities (each pair held for the run under its root plugin with a Revoke), the install and the limits. A Confirm counts only from this page's top frame. No button is focused by default and Confirm arms after a short delay. When hetu stops in the fail-safe it offers Quit, Try again and Start with it switched off. What hetu can't promise: a click proves little, so an over-eager agent with desktop control can click Confirm. A program that injects code into hetu is out of scope.",
  where:"Separate trusted window",trust:"Trusted core page",does:["One pending request at a time, oldest first","Plugins: each plugin and core module with its state and reason, its switch, stop, restart, reset, restore and remove, each item with its switch","Switches: Confirm off for this window and the plugins exec runs any command for","Dev: verification skipped and dev mode per folder plugin, with a count of unsigned builds trusted","Switching a security control off asks you to type the control's id first","Identities: each pair by its field in quotes under its root plugin, a Revoke lasting until hetu quits","Notes: the folder picker, a new folder waits for your Confirm","Limits: each fixed value, set for all plugins or one, every change waiting for your Confirm","Stopped mode: Try again, Start with it switched off and Quit, as far as the failure allows","Restart hetu and Quit"],dec:["Security confirmation in a separate page","Trusted surfaces are core pages"],th:[22,33,58]},

 {id:"install",zone:"zDisk",cls:"disk",x:952,y:56,w:266,h:50,l:["App install"],sub:["read-only · install list"],
  role:"The read-only install in Program Files on Windows, the same code on macOS and Linux. It holds the core with its eleven modules bundled into main, the core plugins and the bundled first-party copies. The install list names each core plugin and each first-party copy with its path, version and hash, so a tampered one fails alone. hetu ships with no package identity or paid signing, so nothing in hetu is keyed to the OS.",
  where:"Program Files on Windows",trust:"Trusted, read-only",does:["hetu-install.json inside app.asar: path, version and hash per core plugin and first-party copy","Core plugins load only from here, switch off only","Packaged builds: ASAR integrity and fuses","The recovery copy for first-party plugins"],dec:["Install and signing"],th:[38,49]},
 {id:"oauthst",zone:"zDisk",cls:"disk",x:952,y:124,w:266,h:42,l:["OAuth state"],sub:["planned · not built"],
  role:"Planned, not built. The OAuth server's records, so a restart loses nothing. Each agent's harness keeps the token itself, hetu doesn't.",
  where:"Data folder, per machine",trust:"Plugin-owned",does:["Server-side records for refresh rotation"],dec:["MCP OAuth spec"],th:[50]},
 {id:"lockm",zone:"zDisk",cls:"disk",x:952,y:184,w:266,h:44,l:["Folder lock · markers"],sub:["hetu.lock · failed-once · starting/"],
  role:"hetu.lock keeps a second hetu off the same data folder. When the event log fails while hetu runs, the plugins manager writes failed-once and hetu starts again. A run that finds the marker and meets the failure again stops in the stopped mode instead of restarting forever. Only a clean Quit or a change applied in the stopped mode clears it. Each control that judges yes or no gets an empty starting/<id> marker before its start, cleared once it started, so a start that hung main stops the next launch in the fail-safe.",
  where:"Data folder, per machine",trust:"Can only hold hetu stopped",does:["One hetu per data folder","A marker can only hold hetu stopped, so it needs no hash","Try again and Restart hetu keep it, a clean Quit clears it","starting/<id>: one empty file per control whose start runs, cleared by Try again"],dec:["One restart, never a loop"],th:[39]},
 {id:"state",zone:"zDisk",cls:"disk",x:952,y:246,w:266,h:58,l:["Security state"],sub:["state/ · format 3 · a hash line per file","only hetu writes it"],
  role:"Per-machine files only hetu writes: state/switches.json, state/luoshu.json and one state/plugins/<id>.json per folder plugin. Each ends in a line holding the hash of every byte above it, checked at start before parsing. A program running as you can still edit, restore or delete these files and one that knows hetu can rewrite the hash too, so this catches careless edits, not a targeted program, which is out of scope.",
  where:"Data folder, per machine",trust:"Hash checked at start",does:["switches.json: core modules and core plugins off, dev mode, verification skipped, unsigned builds trusted, removed first-party copies, any command, limits, confirm off","luoshu.json: the luoshu folder, kept apart from the switches","plugins/<id>.json: version, hash, signer, grants, class, its switch, items off and items that ask at first use","No pair's items: those live in memory for one run","Never in the luoshu, so a synced or cloned luoshu can't bring it along"],dec:["Hash checked on load","State format 3"],th:[22,24,25,54,55]},
 {id:"logs",zone:"zDisk",cls:"disk",x:952,y:322,w:266,h:48,l:["Event log files"],sub:["events/events-<n>.jsonl · hash chain"],
  role:"The local log. A new segment starts after 2 hours idle and the hash chain carries across segments. The same OS user can delete it, so the chain shows gaps and an optional cloud plugin is to keep a copy that survives (planned, not built).",
  where:"Data folder, per machine",trust:"Evidence",does:["Sequence numbers and previous hashes","Every start checks the newest segment against the one before","Never note text, values capped","Optional off-machine copy, planned"],dec:["Detection"],th:[11]},
 {id:"pfolder",zone:"zDisk",cls:"disk",x:952,y:388,w:266,h:50,l:["Plugin folder"],sub:["plugins/<id> · staging"],
  role:"One folder for every folder plugin, first-party copies and community ones alike, hashed by the plugins manager before anything runs. Updates and first-party copies are staged in staging/, swapped in and the state entry written last. It doesn't sync between machines.",
  where:"Data folder, per machine",trust:"Checked against the security state",does:["Package files plus Sigstore signature (signing provenance is designed, not built)","First-party copies kept in step with the install at every start","A removed first-party plugin leaves a tombstone, restore copies it back","A crash between the swap and the entry reads as a failed check"],dec:["Registry v1","First-party plugins in the plugin folder"],th:[24,26,47,49]},
 {id:"storefs",zone:"zDisk",cls:"disk",x:952,y:456,w:266,h:46,l:["Storage · cache"],sub:["storage/<space> · cache/<space>"],
  role:"Each caller's own space, outside its hashed code folder. Each storage key ends in its own hash line and the space has a quota. The cache is rebuildable, unchecked and cleared when the plugin's version changes.",
  where:"Data folder, per machine",trust:"A hash line per key",does:["A key that fails its hash answers tampered","Windows get one space per role for drafts"],dec:["Registry and plugin storage"],th:[24,46]},
 {id:"shadow",zone:"zDisk",cls:"disk",x:952,y:528,w:266,h:50,l:["Shadow repo"],sub:["hetu-owned git dir"],
  role:"hetu's own git history, outside the luoshu under host/history in the data folder, one repo per notes folder. A commit when a plugin asks, naming who made it. hetu owns its whole config, so nothing planted in the luoshu's git config is ever read.",
  where:"Data folder, per machine",trust:"hetu-owned",does:["Attributed history of each commit a plugin asks for, any note read back at a commit","Nothing planted in the luoshu's git config is ever read"],dec:["Shadow repo"],th:[13]},
 {id:"luoshufs",zone:"zDisk",cls:"disk",x:952,y:604,w:266,h:50,l:["Your luoshu"],sub:["markdown notes on disk"],
  role:"Plain markdown on disk. Written only through the luoshu module. Plain text on purpose: reading by a shell agent is out of scope.",
  where:"Your luoshu folder",trust:"Your data",does:["The folder you picked, kept in state/luoshu.json","Watched for outside writes","Read by history byte for byte, never as a git work tree"],dec:["No local encryption"],th:[1,3,8,10]},
 {id:"userrepo",zone:"zDisk",cls:"disk",x:952,y:680,w:266,h:50,l:["Your git repo"],sub:["your own history and backups"],
  role:"Your own repository and backups, exactly as before. hetu never commits to it and never runs git under its config.",
  where:"The luoshu's .git",trust:"Yours, untouched",does:["Your own commits and backups continue","Syncing stays as you set it up"],dec:["Shadow repo leaves it untouched"],th:[13]}
