/* ---------- scenarios ---------- */
var S=[
 {id:"start",name:"Start the program",sum:"From double-click to every module and plugin running and what happens when a check fails.",
  steps:[
   {t:"You launch hetu",n:["human","runtime","boot"],e:["human_launch","runtime_boot"],x:"The runtime runs first, before Electron is ready. The shipped build exits on any argument, a debugging switch included, but --mcp-stdio, which makes it the stdio shim: it relays an agent's stdin and stdout to the local pipe with no boot, no log and no window. Only one hetu runs per data folder, so a second start opens or focuses a window in the first and quits. The sandbox is on for every renderer before any plugin code can run. Then boot takes over.",c:["Debugging switches refused","One instance per data folder"],th:[42]},
   {t:"Boot sets up trust",n:["boot","lockm","state","logs"],e:["boot_lock","boot_state","boot_logs"],x:"Boot takes the folder lock, opens the one event log and loads the security state. It checks each state file against the hash on its last line before the strict parser reads it and writes a format 2 file back once in format 3. A plugin entry that fails doesn't load and nothing else stops. Edited switches fall back to every guard on. A program running as you can edit the files, so the hash catches careless edits, not one that rewrites the hash too.",c:["Hash line checked","Duplicate keys and unknown types rejected"],th:[24,25,54]},
   {t:"Check the install",n:["boot","plugins-manager","runtime","install"],e:["boot_plugins-manager","plugins-manager_install"],x:"The runtime makes a session per role, each in memory and offline with deny-all permission handlers. Boot hands the state to the plugins manager, which reads the install list and hashes each core plugin against it. A mismatch refuses that plugin alone. A list that doesn't check out stops hetu in the stopped mode.",c:["Core plugins checked against the install list"],th:[24,49]},
   {t:"Core modules start",n:["plugins-manager","modules","gate","flood","lock","classifier","storage","luoshu","history","exec","heartbeat","recording","secview"],e:["plugins-manager_modules","modules_gate"],x:"The plugins manager starts the core modules once the install list passed. The controls the fail-safe covers go first and alone: the gate with grants snapshot 1, flood control and the lock module, the guard every note write expects. If one fails, no other module begins, no plugin runs and hetu stops in the fail-safe. Then the grant risk classifier, storage, the luoshu, history, exec and the heartbeat start one at a time, each within a time limit. A module that fails there is marked failed and hetu runs on without it.",c:["Judging controls first and alone","Fail-safe"],th:[35,39]},
   {t:"Check every folder plugin",n:["plugins-manager","install","pfolder","classifier"],e:["plugins-manager_pfolder","plugins-manager_classifier"],x:"First the core plugin from the install starts: mcp-http-handler forks in a utility process of its own. Then the plugins manager brings the first-party copies in step with the install and classes every entry again with the whole table. Then it scans the plugin folder. It reads and hashes each plugin's files once, applies the signer pairing and the reserved ids and parses each manifest with the strict parser. Every result goes in the log. A folder with no entry becomes a new plugin request, never a silent load.",c:["Hash once, run the hashed bytes","A record for every result"],th:[24,26,32]},
   {t:"Start plugins",n:["plugins-manager","runtime","whost","layout","hmarks","httpl"],e:["plugins-manager_runtime","runtime_whost","runtime_http"],x:"The runtime creates the first-party hidden renderer and waits for its worker host page. The layout and hidden marks start as data: workers in graph order, each holding exactly its approved grants. mcp-http-handler, already running, keeps its port and its local pipe closed while no mcp plugin is there. Git and MCP are to start the same way once they are built.",c:["data: workers from the verified bytes","requires resolved first"],th:[29,35]},
   {t:"Record the start",n:["plugins-manager","recording","logs"],e:["plugins-manager_recording","recording_logs"],x:"The plugins manager closes its start with a core.ready core record naming the state of the gate and of the grant risk classifier. An optional cloud plugin that sends a copy off the machine is designed and not built.",c:["Hash chain"],th:[11]},
   {t:"Open the editor window",n:["runtime","eshell","ecore","gate"],e:["runtime_shell"],x:"The editor window opens once the plugins manager's start is done. The drawer gets its verbs from the gate and shows the banner. If hetu stopped in the fail-safe, only the trusted window opens, or a native box while the security view is off.",c:["The window can't touch disk"],th:[42]},
   {t:"If any check failed",n:["boot","plugins-manager","pfolder","state","trusted"],e:["plugins-manager_pfolder","boot_state"],x:"A failed check never means a silent start. The suspect plugin stays off with its reason in the plugin list, edited switches fall back to every guard on and the result is in the log. The banner names each kind of state file that failed its check. A first-party copy can be restored from the install.",c:["Fail closed","Reason in the plugin list"],th:[39],bad:true}
  ]},
 {id:"install",name:"Install a plugin",sum:"From a developer's release to the plugin up and running on your machine.",
  steps:[
   {t:"Developer signs a release",n:["dev","internet"],e:["dev_internet"],x:"The developer's GitHub workflow signs the release keylessly with Sigstore. The signature lands in Rekor, the public append-only log. The signer identity is the repo plus workflow. Signing provenance is designed and not built yet.",c:["No long-lived key to steal"],th:[48]},
   {t:"You add it to the plugin folder",n:["human","internet","pfolder"],e:["internet_pfolder","human_pfolder"],x:"You put the plugin in the one plugin folder, in a folder named by its id. Nothing loads yet.",c:["A file in the folder is not an approval"],th:[]},
   {t:"hetu notices a new plugin",n:["plugins-manager","pfolder"],e:["plugins-manager_pfolder"],x:"At its next start the plugins manager finds a folder with no state entry. Nothing scans the folder again while hetu runs. It reads and hashes the files once, parses the manifest with the strict parser and raises a new plugin request itself. An agent dropping a plugin in hits the same request.",c:["Never a silent load","Unknown capability types refused"],th:[27,54]},
   {t:"Classify it",n:["plugins-manager","classifier"],e:["plugins-manager_classifier"],x:"The plugins manager hands the grant risk classifier the whole table with the new plugin in it. The classifier computes the class from everything the plugin can reach through plugin.call and events, never from what it declares. It also writes the screen lines and names every other plugin whose class the change moves. Read plus network together ranks class 4.",c:["Class computed, never declared","Combination rules"],th:[27]},
   {t:"See exactly what it asks for",n:["runtime","trusted"],e:["runtime_trusted"],x:"The banner shows a notice for the request and clicking it has the runtime open the trusted window. The page draws the change in the core's own words first, then the version, every permission it asks for and the grant risk classifier's lines, all as plain text. Approval is all or nothing, so the permission design stays with the plugin's maker. No signer shows yet, since signing provenance is designed and not built.",c:["All or nothing","Every permission shown"],th:[33]},
   {t:"Approve with a Confirm click",n:["human","trusted","router","secview"],e:["human_trusted","trusted_router","plugins-manager_secview"],x:"You click Confirm once it arms. The router takes it only from the trusted window's top frame on hetu://trusted, checked first. The security view says whether the click counts. If a state file changed since the request, the answer is stale and nothing applies.",c:["Only Confirm in the trusted window approves"],th:[22,33]},
   {t:"Record first, then write the state",n:["router","recording","logs","plugins-manager","state","modules","gate"],e:["router_plugins-manager","plugins-manager_recording","recording_logs","plugins-manager_state","modules_gate"],x:"The core writes the Confirm record. Once it is on disk the plugins manager applies exactly the stored change: the plugin's entry with its hash, grants and class and no signer, since signing provenance is designed and not built. The gate gets a new grants snapshot.",c:["Widening applies after its record","Hash pinned at approval"],th:[11,47]},
   {t:"Start the plugin",n:["plugins-manager","router","runtime","community"],e:["plugins-manager_router","plugins-manager_runtime","runtime_comm"],x:"With no signer the approved plugin is refused as unsigned until you switch dev mode on for it in the trusted window, which also skips its hash check, since no button yet trusts one unsigned build by its hash. Then the plugins manager mints the plugin's port and registers it with the router in the same step. The runtime starts it as a data: worker in a hidden renderer of its own, from the bytes the plugins manager hashed. Its views mount in the editor window when you open one.",c:["Worker sandbox","Grants from the security state"],th:[26,29]},
   {t:"Its first request",n:["community","router","flood","gate","recording"],e:["comm_router","router_flood","router_gate","router_recording"],x:"Every action the plugin takes is a call the router checks, flood control counts, the gate decides and recording records. It has no power of its own.",c:["Precheck before route","Recorded"],th:[30,31]}
  ]},
 {id:"update",name:"A plugin update arrives",sum:"Which updates load without a prompt, which ask you and when hetu warns.",
  steps:[
   {t:"A new version appears",n:["dev","internet","pfolder"],e:["dev_internet","internet_pfolder"],x:"The developer publishes a new signed release. The plugins manager stages it beside the old version, never over it. Nothing in hetu fetches or stages a new version yet: the update steps below are built, the way a new version reaches them is not.",c:[],th:[]},
   {t:"Same signer?",n:["plugins-manager","pfolder","state"],e:["plugins-manager_pfolder"],x:"The plugins manager compares the signer identity with the one pinned at first approval. A different identity, even with a valid signature, is treated as a new plugin with a warning. That stops a forked plugin with a backdoor. Signing provenance is designed and not built yet, so this check doesn't run today.",c:["Signer must match the pin"],th:[47]},
   {t:"Does it still fit?",n:["plugins-manager"],e:[],x:"The plugins manager resolves the update against the live plugin graph. One that closes a cycle or leaves a running plugin without what it requires is refused or needs a Confirm naming the plugins it stops.",c:["Resolved against the live graph"],th:[]},
   {t:"Class 0 loads without a prompt",n:["plugins-manager","classifier","community"],e:["plugins-manager_classifier"],x:"An update skips the Confirm only when the grant risk classifier answers that it may: its entry holds class 0, the whole table still classes it 0, it asks for nothing it doesn't hold and it holds no layout item. With the classifier off or down, every update asks. An update that asks for more needs your approval again, whatever its class.",c:["Only class 0 skips the Confirm","Widened manifest asks again"],th:[28,48]},
   {t:"Everything else asks you",n:["human","trusted","router","plugins-manager","state"],e:["human_trusted","trusted_router","router_plugins-manager","plugins-manager_state"],x:"For class 1 and up you approve the update with a Confirm click. Its record lands first, then the plugins manager writes the entry.",c:["A Confirm click per update"],th:[48]},
   {t:"Swap and restart",n:["plugins-manager","pfolder","runtime","community"],e:["plugins-manager_pfolder","plugins-manager_runtime","runtime_comm"],x:"The staged folder is swapped in and the state entry written last. The old incarnation stops and the new one starts on a new port. A crash between the swap and the entry reads as a failed check.",c:["Entry written last"],th:[26]},
   {t:"First-party never comes this way",n:["plugins-manager","install","pfolder"],e:["plugins-manager_install","plugins-manager_pfolder"],x:"Core modules and core plugins change only with an app update. The plugins manager checks each core plugin against the install list and clears its cache when the version changes. First-party folder plugins are copied from the install at start, never fetched through the plugin channel.",c:["Core ships inside the app install"],th:[49]}
  ]},
 {id:"agent",name:"An agent edits a note",sum:"How an MCP client is to reach a note and what the core already judges for it. The MCP plugin, OAuth and leases are planned.",
  steps:[
   {t:"First call without a token",n:["agent","httpl"],e:["agent_http","agent_pipe"],x:"The agent calls hetu's MCP endpoint on 127.0.0.1:4747. The handler is bound only while an mcp plugin is there, so with none built it stays closed. Once open, a request with no token gets a 401 with a bare WWW-Authenticate: Bearer. An agent that speaks MCP over stdio starts hetu --mcp-stdio instead, the shim, which relays it to a local pipe the handler serves beside the port and keeps closed the same way.",c:["Loopback only, Host and Origin checks"],th:[14,15]},
   {t:"OAuth with PKCE (planned)",n:["agent","oauth","internet"],e:["agent_oauth","oauth_internet"],x:"Planned. The agent starts OAuth 2.1 with PKCE. If it identifies with a client metadata URL, hetu fetches it over HTTPS only and never from private or loopback addresses.",c:["HTTPS only","No private addresses"],th:[51]},
   {t:"Connect the client",n:["httpl","router","trusted","human"],e:["oauth_router","human_trusted"],x:"The handler asks the core to connect a new client through core.consentAsk. The trusted window shows the client id, its name and where it returns, or that it reaches hetu over the local pipe, with a warning that any program on the machine can claim that id. A Confirm changes no state: the handler then gives each of the client's connections a label of its own. The handler asks this for each new client on the local pipe, which stays closed while no mcp plugin is there.",c:["Connect in the trusted window"],th:[9]},
   {t:"Short-lived token (planned)",n:["oauth","agent","oauthst"],e:["agent_oauth","oauth_state"],x:"Planned. The agent receives a short-lived access token bound to hetu. Its harness stores the token, not hetu. Refresh tokens rotate and reuse of an old one revokes the chain and alerts you.",c:["Short-lived","Reuse detection"],th:[50]},
   {t:"The call reaches MCP",n:["agent","httpl","router","gate","mcp"],e:["agent_http","agent_pipe","http_router","router_gate","router_mcp"],x:"mcp-http-handler checks the label's form, client id plus # plus a number, or on the pipe gives the connection its label itself. It calls mcp.handle over its own port with that label as onBehalf. The gate judges that root call on the handler's own plugin.call item. From here the chain carries a pair: mcp-http-handler plus the label. The core has no agents of its own and onBehalf alone grants nothing.",c:["The handler checks the label","onBehalf grants nothing"],th:[9,40]},
   {t:"Ask for the pair's items",n:["mcp","router","plugins-manager","trusted","human"],e:["mcp_router","router_plugins-manager","human_trusted"],x:"The MCP plugin asks through core.identityAsk for what the pair lacks, only from under the root call. A pair may hold luoshu.read, luoshu.list, luoshu.write, history and lock.set only. The trusted window names the field in quotes under its root plugin. A Confirm grants the items in memory until hetu quits. Cancel and revoke, or Revoke in the identities list, turns the pair away for the rest of the run.",c:["For one run, in memory","Five types only"],th:[9,40]},
   {t:"Ask for a lease (planned)",n:["mcp","router","gate","leases","lock"],e:["mcp_router","leases_router","router_gate","router_lock"],x:"Planned. The MCP plugin is to call the leases plugin under the same chain, which decides which notes the agent gets and for how long and locks them with lock.set. The lock module that holds the locks is built: it keys the holder by the chain's root plugin plus the whole onBehalf label, never a name in the arguments, so a second agent can't write under the first one's lock. A lock lasts at most 30 minutes.",c:["Lock keyed by root plugin and label"],th:[1,6,40]},
   {t:"Refused? Only a code",n:["lock","mcp"],e:[],x:"If another holder locks the note, lock.set and the write both answer locked, a fixed code that never names another agent's lock or id. That's the A-05 lesson.",c:["A refusal names nothing of another caller"],th:[6,37]},
   {t:"Edit the note",n:["mcp","router","gate","luoshu","lock","luoshufs"],e:["mcp_router","router_gate","router_luoshu","router_lock","luoshu_luoshufs"],x:"luoshu.write takes the eleven steps. The gate's precheck checks the MCP plugin's own luoshu.write item and the pair's both. The luoshu turns the path into a canonical one and takes its latch, the gate decides again on that path and the lock guard refuses it when another holder locks the note. Then the luoshu checks the version and writes the file.",c:["Caller and pair both","Canonical path before decide","Version check"],th:[1,2,3]},
   {t:"Tell the others",n:["luoshu","bus","gate","community","eshell"],e:["luoshu_bus","bus_gate","bus_hidden","bus_shell"],x:"The luoshu publishes luoshu.changed. The bus asks the gate's canList for each subscriber and sends a signal plus the path, never the content, to each editor window and any plugin subscribed whose list or read items cover the note.",c:["canList on every delivery"],th:[37]},
   {t:"Commit to the shadow repo",n:["router","history","osproc","shadow","luoshufs"],e:["router_history","history_proc","proc_shadow","history_luoshu"],x:"History commits the edit in hetu's own repo with git plumbing only and a clean environment. Under the pair, mcp-http-handler is the committer and the label is the author. Your own repo is untouched. Which plugin asks for that commit is settled when leases and git are built.",c:["Plumbing only","Luoshu git config never read"],th:[13,45]},
   {t:"Everything was recorded",n:["router","recording","logs"],e:["router_recording","recording_logs"],x:"Each call above is an audit record with the caller, the agent's label and the outcome. Recording writes the records in batches beside its own core records.",c:["Hash chain"],th:[11]}
  ]},
 {id:"type",name:"You type, a plugin decorates",sum:"The editor, the bridge, edits from a plugin and saving as your window.",
  steps:[
   {t:"You type",n:["human","ecore"],e:["human_ecore"],x:"Keystrokes go straight to CodeMirror in the drawer. No plugin's code runs in the page: hidden marks is a first-party worker that hears of the change like any plugin and sends its marks back over its port.",c:["No plugin code in the page"],th:[]},
   {t:"Plugins hear about it",n:["ecore","eshell","hmarks"],e:[],x:"The drawer tells each plugin worker that reads the note that it changed, with the change set and the new version, over that plugin's own port. A plugin that can't read the note hears nothing about it.",c:["Readers only"],th:[41]},
   {t:"A plugin sends decorations",n:["hmarks","eshell","ecore"],e:["hmarks_shell","shell_ecore"],x:"Hidden marks sends CodeMirror-shaped marks for the version it saw. The drawer maps them through what you typed since and draws them with its own classes. Widgets are text only. Measured on a 2,000-line note, a mark comes back about a millisecond after the character it follows is on screen.",c:["Its own styles only","No HTML widgets","Mapped to the right text"],th:[19,41]},
   {t:"A plugin sends an edit",n:["community","eshell","ecore"],e:["shell_ecore"],x:"A table formatter sends a change list against version N. If you typed elsewhere since, the drawer rebases it, as CodeMirror's collaboration guide recommends. It is refused only when it touches text you changed since. An applied edit is the plugin's.",c:["Rebased, refused only on a clash","The plugin's edit"],th:[41]},
   {t:"Save as your window",n:["ecore","router","gate","luoshu","luoshufs"],e:["ecore_router","router_gate","router_luoshu","luoshu_luoshufs"],x:"The editor saves over window IPC with the version it read. The router checks the sender first and then the window's fixed grants. The save takes the same steps as every other write and is recorded as yours, naming the plugins whose edits it carries. A save over a note changed outside keeps your text as a draft, as does one over a note another holder locks, where Take over clears that lock with no Confirm. Your draft stays until the save lands.",c:["Sender checked first","Attributed to you and the plugins that edited"],th:[19,42]},
   {t:"Raw view tells the truth",n:["human","ecore"],e:["human_ecore"],x:"Ctrl+/ draws the raw view over the whole window, which ignores every plugin decoration. A decoration can never hide text from you there.",c:["Raw view in-page, unreachable by plugins"],th:[8]}
  ]},
 {id:"guardoff",name:"Switch security off",sum:"How you switch security off on purpose, what still holds and why nothing else can.",
  steps:[
   {t:"You choose to switch it off",n:["human","trusted"],e:["human_trusted"],x:"The switches in the trusted window cover every core module and plugin, the gate and recording included. Only a hetu window can ask for a change, never a plugin or MCP.",c:["Never over MCP, never by a plugin"],th:[22]},
   {t:"The request",n:["trusted","router","plugins-manager","secview"],e:["trusted_router","router_plugins-manager","plugins-manager_secview"],x:"The window sends security.request. The core reads from the change's structure whether it widens and the security view says whether it waits. Switching the gate off widens, so it waits for a Confirm. The security path never asks the gate, so a failed gate can't block it.",c:["security actions refused for every plugin","Never asked of the gate"],th:[22,39]},
   {t:"Your Confirm click",n:["human","trusted","router"],e:["human_trusted","trusted_router"],x:"The page draws the exact change. Confirm arms after a short delay and counts only from the trusted window's top frame. To switch a security control off, you first type the control's id.",c:["Your Confirm click"],th:[33]},
   {t:"Record first, then apply",n:["router","recording","logs","plugins-manager","state","modules","gate"],e:["router_plugins-manager","plugins-manager_recording","recording_logs","plugins-manager_state","plugins-manager_modules"],x:"The core writes who switched what and when. Once that record is on disk the plugins manager writes the switch into the per-machine state, never into the luoshu. The gate's step then acts as if it didn't exist. Plugins start or stop to match and subscriptions are asked again.",c:["Applies after its record","Per machine"],th:[11,22]},
   {t:"A banner while it's off",n:["eshell","trusted"],e:[],x:"Every window's banner shows what is off for as long as it stays off. The trusted window says that per-item switches lapse while the gate is off.",c:["Visible state"],th:[22]},
   {t:"Gate off: allow all",n:["router","gate","exec","recording","logs"],e:["router_recording","recording_logs"],x:"Every call with power passes the gate's step, whatever the log's state, which decides nothing. The floor and the guards still hold and exec still checks each plugin's declared commands, where an exec item you switched off counts for nothing. Calls are still recorded while recording is on. No open call is judged again while the gate is off.",c:["Floor, guards and exec's list still hold","The log decides nothing"],th:[11,45]},
   {t:"Three more switches",n:["trusted","exec","router","recording"],e:[],x:"exec can run any command for a plugin you name. An exec item you switched off stays refused with the gate off too. Limits can be raised per plugin or for all. Recording can be switched off and that switch is the last record until recording is back on. Each widens, so each needs a Confirm and shows in the banner. No switch hands a plugin or an agent a power the framework doesn't have.",c:["A Confirm and the banner for each","No switch gives a plugin Node or a security change"],th:[22]},
   {t:"A crash is not a switch",n:["gate","flood","lock","modules","router"],e:["router_gate","router_flood","router_lock"],x:"A control that judges yes or no and crashes in use refuses: a gate that can't take a grants snapshot answers policy-down to every call with power, a throw in flood control drops that message or fails that call and a lock guard that throws or answers late refuses the write as guard-down. One that fails at start stops hetu in the fail-safe with Quit, Try again and Start with it switched off. Only your click turns security off.",c:["Fail closed","Fail-safe at start"],th:[39],bad:true}
  ]},
 {id:"gatedown",name:"The gate fails",sum:"What happens when the gate fails without you switching it off and the way back.",
  steps:[
   {t:"The gate throws",n:["router","gate","modules"],e:["router_gate","modules_gate"],x:"A throw inside decide or canRead refuses that one call and the fault is recorded. A throw when a new grants snapshot arrives marks the gate failed until the next one goes through.",c:["A throw refuses"],th:[39]},
   {t:"Calls with power fail closed",n:["router","gate","community","ecore"],e:["comm_router","router_gate"],x:"Calls with power answer policy-down, open ones included when a new grants snapshot can't be judged. Windows get no luoshu access. Plugins keep running and see a refusal code, as with any refusal.",c:["policy-down","Plugins keep running"],th:[39]},
   {t:"Events wait",n:["bus","gate","community"],e:["bus_gate","bus_hidden"],x:"While the gate is down no path event goes out and new subscriptions wait. Once the gate allows delivery again, each path subscriber gets one events.dropped to resync.",c:["Path events held back"],th:[37]},
   {t:"The banner shows it",n:["eshell","recording","logs"],e:["recording_logs"],x:"The banner shows the gate's state and a core record names it. Free calls still work: a plugin's own storage, cache and topics need no gate.",c:["Banner","Core record"],th:[11]},
   {t:"The way back",n:["human","trusted","router","plugins-manager"],e:["human_trusted","trusted_router","router_plugins-manager"],x:"Security changes never ask the gate, so a failed gate can't block the way out. Switching the gate off with a Confirm lets every call pass, still recorded. The next grants snapshot tries the gate again and so does Restart hetu.",c:["The way out never asks the gate"],th:[39]},
   {t:"Failed at start",n:["gate","modules","plugins-manager","trusted"],e:["plugins-manager_modules","modules_gate"],x:"If the gate's first grants snapshot throws at start, no other module begins and no plugin runs. hetu stops in the fail-safe: Quit, Try again, or Start with it switched off, which counts as switching it off with its Confirm. No restart marker is written, so it never starts again on its own. A hang inside the gate freezes main until a force-quit, since the gate has no start of its own that a time limit could cut. The start marker it leaves sends the next launch to the fail-safe.",c:["Fail-safe","A hang freezes main"],th:[39],bad:true}
  ]},
 {id:"replay",name:"Shell agent goes after security",sum:"An agent with a shell changes hetu's security state without you. What hetu catches and what it doesn't.",
  steps:[
   {t:"It edits the state",n:["shell","state"],e:["shell_state"],x:"The agent edits switches.json to switch a guard off. A program running as you can write the file, so nothing stops the edit. At the next start the hash line doesn't match. Edited switches fall back to every guard on and an edited plugin entry means that plugin doesn't load. Nothing else stops and hetu records the result.",c:["Caught at start","Fail closed"],th:[24]},
   {t:"It rewrites the hash too",n:["shell","state"],e:["shell_state"],x:"An agent that knows hetu rewrites the hash or puts back an older copy with its own hash. That isn't caught. Deleting switches.json is caught as gone while the event log or other state shows hetu ran here before, but deleting the state with the log reads as a new install on defaults. hetu treats a program that targets it as out of scope: it can already read and edit your notes directly, so a stronger lock on the state alone would guard one door beside an open wall.",c:["Not caught","Accepted: detect only"],th:[24,25,55],bad:true},
   {t:"It tries to fool you instead",n:["shell","trusted","human"],e:["shell_ui"],x:"It could also inject code into hetu and show you one change in the trusted window while asking for another. Or it could drive the desktop and click Confirm itself. A program that targets hetu is out of scope and editing the state directly is easier.",c:["Out of scope","Accepted risk"],th:[58],bad:true},
   {t:"What is on record",n:["boot","recording","logs"],e:["boot_logs","recording_logs"],x:"Every check at start goes in the event log. A program running as you can delete or cut the log too. The hash chain catches a line edited or removed by a tool that doesn't recompute it and a rotated file cut or deleted, but not a deleted newest file. An optional cloud plugin that keeps a copy off the machine is designed and not built.",c:["Hash chain"],th:[11]}
  ]},
 {id:"hang",name:"A plugin hangs",sum:"The heartbeat watches, the core marks and terminates and you can stop it too.",
  steps:[
   {t:"Heartbeat goes unanswered",n:["heartbeat","plugins-manager","community"],e:["plugins-manager_heartbeat","heartbeat_plugins-manager"],x:"The heartbeat has the plugins manager ping every running plugin every 5 seconds. After three misses in a row it asks the core to mark a worker unresponsive, not crashed.",c:["Heartbeat","Three misses"],th:[36]},
   {t:"Its roles count as down",n:["router","community","plugins-manager"],e:["comm_router"],x:"Calls to it answer timeout at once and its events stop. Nothing is closed and plugins that depend on it keep running. It returns to ready if it answers again. A utility half that stops answering is killed and reads crashed instead.",c:["timeout at once"],th:[36]},
   {t:"Or you stop it",n:["human","trusted","router"],e:["human_trusted","trusted_router"],x:"The plugin list in the trusted window stops or restarts any sandboxed plugin. Restarting widens nothing, so it needs no Confirm.",c:["Stop from the trusted window"],th:[36]},
   {t:"Terminate",n:["router","plugins-manager","runtime","community"],e:["router_plugins-manager","plugins-manager_runtime","runtime_comm"],x:"The plugins manager stops the plugin and the runtime ends its worker with terminate(), which stops even a busy loop. A restart runs the bytes already verified as a new incarnation on a new port. The stop is recorded.",c:["terminate()","New incarnation"],th:[36]},
   {t:"If it floods instead",n:["community","router","flood"],e:["comm_router","router_flood"],x:"Flood control counts every message at the way in. Messages over the rate are dropped with no reply. A port over the flood cap is closed and the plugin is marked crashed. Calls and bytes in flight per caller are capped too.",c:["Rate counted at the way in","Flood cap"],th:[7,36]},
   {t:"With the heartbeat off",n:["human","trusted","heartbeat"],e:["human_trusted"],x:"Switching the heartbeat off widens, so it waits for one Confirm with no typed word. While it is off nothing is pinged or marked and a call to a hung plugin fails on its own deadline.",c:["One Confirm"],th:[36]}
  ]},
 {id:"writerun",name:"Plugin tries write-then-run",sum:"A malicious plugin with an exec grant tries to run code it wrote itself.",
  steps:[
   {t:"It writes a script into its storage",n:["community","router","storage","storefs"],e:["comm_router","router_storage","storage_fs"],x:"Storage is free and always granted, so writing helper.js into its own space succeeds.",c:["Own space only"],th:[46],bad:true},
   {t:"It asks to run it",n:["community","router","gate","exec"],e:["comm_router","router_gate","router_exec"],x:"Its manifest declared the exact command node <storage>/helper.js and you approved it with a Confirm. The string matches exactly.",c:["Exact match passes"],th:[46],bad:true},
   {t:"Refused",n:["exec","router","recording"],e:["router_recording"],x:"exec refuses a command whose program or argument names a file in the notes folder or in hetu's data folder, where storage lives, by real path. A path inside a longer string, such as code handed to -c, isn't seen. The refusal is recorded.",c:["No file in the notes or data folder is named"],th:[46]},
   {t:"Even a clean command is pinned",n:["exec","osproc"],e:["exec_proc"],x:"Allowed commands run with an environment the core builds: absolute paths, a new empty working folder and no NODE_OPTIONS or similar.",c:["Clean environment"],th:[45]},
   {t:"The gate off changes nothing here",n:["exec","gate"],e:[],x:"With the gate off, exec still checks each call against the plugin's declared commands, along with the environment and write-then-run rules. Only your own switch, any command for that plugin, lifts the list, with a Confirm and a banner.",c:["Checked with the gate off too"],th:[45,46]}
  ]},
 {id:"direct",name:"Shell agent edits a note directly",sum:"An agent writes a note on disk, going around hetu.",
  steps:[
   {t:"It writes the file",n:["shell","luoshufs"],e:["shell_luoshu"],x:"An agent with a shell edits a note directly, bypassing the router and the luoshu.",c:[],th:[10],bad:true},
   {t:"The watcher sees it",n:["luoshu","luoshufs","bus"],e:["luoshu_watch","luoshu_bus"],x:"The luoshu's watcher compares the file with its own writes and publishes luoshu.outside. Subscribers whose list or read items cover the note hear a signal and the path.",c:["Detection only"],th:[10]},
   {t:"Recorded as unknown",n:["gitp","router","history","osproc","shadow"],e:["hidden_router","router_history","history_proc","proc_shadow"],x:"Nothing commits on its own yet. Once the git plugin exists, the next commit to the shadow repo marks the change as made by an unknown writer, never under an agent's name. History keeps the version before.",c:["Attribution","Revertable"],th:[10]},
   {t:"No silent overwrite",n:["lock","luoshu","router"],e:["router_luoshu"],x:"An agent or a window that read the note before the outside edit writes against the old version, so its next write fails the version check and nothing is silently overwritten. A lock keeps other holders inside hetu off a note, never a program going around hetu.",c:["Version check"],th:[2,10]}
  ]}
];
